/**
 * Country metadata for the phone-number field: ISO-3166-1 alpha-2, English name, E.164 calling
 * code, and an example national number, for every country `libphonenumber-js/mobile` can
 * validate a mobile number in.
 *
 * Generated — do not edit by hand. Flags are derived from the ISO code at render time rather
 * than stored, so there is no image table to keep in step (see `flagFor` in `./phone`).
 */

export interface CountryInfo {
  /** ISO-3166-1 alpha-2. */
  readonly code: string;
  readonly name: string;
  /** E.164 calling code, without the leading `+`. */
  readonly dialCode: string;
  /** An example national number, grouped as the input groups it. */
  readonly placeholder: string;
}

